"""Independent reference helpers + runner for exercising the candidate."""
import hashlib, json, struct, subprocess, sys

CWD = '/workspace/project'

def run_obj(obj):
    return run_raw(json.dumps(obj))

def run_raw(raw):
    if isinstance(raw, str):
        raw = raw.encode('utf-8')
    p = subprocess.run(['python3', '-B', 'main.py'], input=raw,
                       capture_output=True, cwd=CWD)
    out = p.stdout
    assert p.returncode == 0, ('exit', p.returncode, p.stderr[:500])
    return json.loads(out)

def fp(data):
    n = len(data)
    h = 0
    for i, b in enumerate(data):
        h = (h + (b + 1) * pow(257, n - 1 - i, 1 << 64)) % (1 << 64)
    return {'n': n, 'h': format(h, '016x')}

def act(t, s, kind, content, end):
    out = struct.pack('>QI', t, s) + kind.encode('ascii')
    if kind in ('H', 'h'):
        out += struct.pack('>Q', len(content))
        for name, value in content:
            out += struct.pack('>Q', len(name)) + name
            out += struct.pack('>Q', len(value)) + value
    else:
        out += struct.pack('>Q', len(content)) + content
    out += b'\x01' if end else b'\x00'
    return out

def enc_pairs(pairs):
    out = struct.pack('>Q', len(pairs))
    for name, value in pairs:
        out += struct.pack('>Q', len(name)) + name
        out += struct.pack('>Q', len(value)) + value
    return out

def rnd(seed, coordinate, occurrence):
    return hashlib.sha256(f'{seed}/{coordinate}/{occurrence}'.encode()).hexdigest()[:20]

FAILURES = []

def check(name, cond, detail=''):
    if cond:
        print('ok  ', name)
    else:
        print('FAIL', name, detail)
        FAILURES.append(name)

def summary():
    if FAILURES:
        print('FAILURES:', len(FAILURES))
        sys.exit(1)
    print('ALL TESTS PASSED')
